# Builds battles/first-manassas/battle.json. Run from the repo root: python3 battles/first-manassas/make.py
# Local metres from 38.8150N 77.4900W (x east, y north). The 11 km square holds Centreville (5061,2643), the fords
# from Sudley to Blackburn's, the Stone Bridge (-1189,1039) and the Henry House (-2830,-20). Every place is kept in
# latitude and longitude below and converted once. Streams and the modern roads on the 1861 lines (US 29 on the
# Warrenton Turnpike, VA 234 on the Manassas-Sudley road) come from OpenStreetMap. The fords, farm roads, Pittsylvania,
# Van Pelt's, Portici and the wartime woods are read off the Park Service map of the battle (GMP 2005, figure A-2),
# georeferenced on six houses to within about 100 m. The flank-march road is placed from the narrative, within a few
# hundred metres. Quarries the DEM shows by the turnpike, north of Sudley and on the Sudley road are filled.
import json, math, datetime as dt
HERE = "battles/first-manassas/"
LAT0, LON0 = 38.8150, -77.4900
KX, KY = 111320 * math.cos(math.radians(LAT0)), 111320  # tools/fetch_terrain.py's metres per degree
def M(lat, lon): return (round((lon - LON0) * KX), round((lat - LAT0) * KY))

# ---- terrain: fill the modern quarries with a smooth (harmonic) surface from their rims ----
T = json.load(open(HERE + "terrain.json"))
COLS, SP = T["cols"], T["spacing"]; HALF = COLS * SP / 2
QUARRIES = [(-700, 300, 400, 1650), (-4450, 3550, -3950, 4250), (-3700, -4300, -2200, -3200)]  # x0, y0, x1, y1 in metres
def fill(x0, y0, x1, y1):
    Z = T["z"]; c0, c1 = int((x0 + HALF) / SP), int((x1 + HALF) / SP); r0, r1 = int((HALF - y1) / SP), int((HALF - y0) / SP)
    rim = [Z[r * COLS + c] for r in (r0, r1) for c in range(c0, c1 + 1)] + [Z[r * COLS + c] for c in (c0, c1) for r in range(r0, r1 + 1)]
    v = {(r, c): sum(rim) / len(rim) for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)}
    get = lambda r, c: v.get((r, c), Z[r * COLS + c])
    for _ in range(3000):  # over-relaxed Gauss-Seidel; the result depends only on the rim, so a second run changes nothing
        worst = 0
        for (r, c), old in v.items():
            new = old + 1.9 * ((get(r - 1, c) + get(r + 1, c) + get(r, c - 1) + get(r, c + 1)) / 4 - old); v[(r, c)] = new; worst = max(worst, abs(new - old))
        if worst < 1e-4: break
    for (r, c), val in v.items(): Z[r * COLS + c] = round(val, 1)
before = list(T["z"])
for q in QUARRIES: fill(*q)
if T["z"] != before: json.dump(T, open(HERE + "terrain.json", "w"), separators=(",", ":"))
def z(x, y):
    c, r = int((x + HALF) / SP), int((HALF - y) / SP)
    return T["z"][r * COLS + c] if 0 <= c < COLS and 0 <= r < COLS else 999

