# Hold in place through long gaps: without this a unit creeps toward a key hours away and the time-lapse never engages.
def add_holds(ks):
    out = []
    for a, c in zip(ks, ks[1:] + [None]):
        out.append(a)
        if c is None or a.get("state") == "hidden": continue
        moved = (a["x"], a["y"]) != (c["x"], c["y"]); gap = sec(c["t"]) - sec(a["t"])
        if moved and gap > 3 * 3600: out.append(dict(t=fmt(sec(c["t"]) - 900), x=a["x"], y=a["y"]))
    return out
assert set(KEYS) == {row[0] for row in OOB}, set(KEYS) ^ {row[0] for row in OOB}
units = []
for id, side, short, name, commander, type, strength, extra in OOB:
    ks = add_holds(KEYS[id])
    bad = [(a["t"], b["t"]) for a, b in zip(ks, ks[1:]) if sec(b["t"]) < sec(a["t"])]
    assert not bad, (id, bad)
    units.append(dict(id=id, side=side, name=name, short=short, commander=commander, type=type, strength=strength, keys=ks, **extra))
# Ricketts's and Griffin's guns changed hands three times and were never fired again; a unit keeps its side, so after the
# gunners went down the guns themselves are drawn as a battery where they stood.
def gun_park(p, h, w=70, d=24):
    return [list(map(round, off)) for off in [(p[0] + dx * math.cos(math.radians(h)) + dy * math.sin(math.radians(h)), p[1] - dx * math.sin(math.radians(h)) + dy * math.cos(math.radians(h)))
                                               for dx, dy in [(-w / 2, -d / 2), (w / 2, -d / 2), (w / 2, d / 2), (-w / 2, d / 2)]]]
features += [dict(type="battery", poly=gun_park(P['ricketts_guns'], 95), **{"from": "15:00"}), dict(type="battery", poly=gun_park(P['griffin_guns'], 85), **{"from": "15:00"}),
             dict(name="the guns, taken and retaken", at=[P['griffin_guns'][0] - 60, P['griffin_guns'][1] - 110], **{"from": "15:00"})]

# Chapters: (time, title, text, camera centre, metres across, playback speed, clock time the sources record or None).
# The morning follows Wilshin's times and the afternoon the Park Service's; where they disagree the caption says so.
CHAPTERS = [
    ("02:30", "The march from Centreville", "Under a moon a day short of full, McDowell's army leaves its camps round Centreville at half past two. Tyler's division takes the Warrenton Turnpike to make a show at the Stone Bridge; Hunter's and Heintzelman's follow it, to turn off past Cub Run and go round by Sudley Springs onto the Confederate left. About 18,000 men will cross Bull Run. The road is choked and the column crawls.", [3500, 2500], 3600, 300, "2:30 AM"),
    ("05:15", "The first gun", "Tyler's head halts before the Stone Bridge. Lieutenant Hains's 30-pounder Parrott fires down the turnpike, the first shot of the day: a quarter past five by Wilshin, half past by the Park Service. Evans, holding the bridge with eleven companies and two guns, does not answer. Across the valley the Union guns at Blackburn's Ford open too.", [-800, 1150], 2600, 120, "about 5:15 AM"),
    ("05:30", "The road through the woods", "At the blacksmith's shop half a mile past Cub Run, Hunter's division turns right onto a narrow track through the woods, Heintzelman's behind it. It was to reach Sudley Springs by seven; the road is twice as long as anyone thought, and the head will not get there until half past nine. Howard's brigade halts at the turn as a reserve.", [-500, 3300], 5000, 300, None),
    ("07:00", "The Confederate right", "Beauregard means to attack Centreville with his right. D. R. Jones has crossed McLean's Ford to wait for Ewell, who never gets the order; Longstreet lies under the Union guns across Blackburn's Ford. Seeing columns moving to the north, Beauregard sends Jackson's brigade about seven to the gap between Bonham and Cocke, and Bee and Bartow toward the Stone Bridge.", [2400, -2000], 4500, 300, "about 7 AM"),
    ("08:45", "You are turned", "From the signal station on Wilcoxen's farm Captain Alexander sees the glint of guns and bayonets near Sudley and flags Evans: 'Look out for your left; you are turned.' Evans leaves four companies at the bridge and takes the rest by the Carter farm to Matthews Hill. Wilshin has it at a quarter to nine, the Park Service at nine.", [-2500, 1250], 3300, 60, "8:45 AM"),
    ("09:30", "Sudley Springs", "Hunter's head fords Bull Run at Sudley Springs at half past nine and halts so the men can drink. Then it comes on down the Manassas-Sudley road toward Evans's skirmishers.", [-3900, 2300], 2600, 60, "9:30 AM"),
    ("10:15", "Matthews Hill", "Burnside's 2nd Rhode Island walks into Evans's line on Matthews Hill; its battery and the rest of the brigade come into line beside it. Wheat's Louisianans charge and are shot back, Wheat badly wounded. Evans's 900 hold the head of Hunter's column for an hour. Wilshin puts the attack at a quarter past ten, Fry at a quarter to.", [-3550, 1300], 1700, 30, "about 10:15 AM"),
    ("11:00", "Bee and Bartow", "Bee and Bartow bring five regiments up on Evans's right, with Imboden's guns firing from Henry Hill behind them; the 8th Georgia goes into a thicket ahead of the line and is cut to pieces. Porter's brigade comes in on Burnside's right, Sykes's regulars on his left.", [-3450, 1250], 1700, 30, "about 11 AM"),
    ("11:30", "The line breaks", "Outflanked by Porter, with Heintzelman's division coming down the road behind him, the Confederate line breaks about half past eleven and runs back over Young's Branch and the turnpike. Hampton's Legion, off the train that morning, stands by the Robinson house to cover it and loses heavily.", [-3000, 650], 2300, 30, "11:30 AM"),
    ("11:50", "A stone wall", "Jackson has formed his five Virginia regiments behind the crest of Henry Hill with thirteen guns in front of them. Bee, trying to rally his brigade, points to them: 'There is Jackson standing like a stone wall.' Johnston and Beauregard come up; Johnston goes back to Portici to send on the reinforcements.", [-2550, -80], 1700, 60, "about noon"),
    ("12:10", "The Farm Ford", "Ordered over about noon, Sherman takes his brigade across Bull Run at a ford 800 yards above the Stone Bridge, where he had seen a horseman cross; Keyes follows. Their guns cannot climb the far bluff. Sherman forms behind Porter's brigade on Matthews Hill.", [-2300, 1350], 3000, 60, None),
    ("12:45", "The lull", "For two hours the Union regiments re-form north of Young's Branch while McDowell readies an attack on Henry Hill; Ricketts's and Griffin's batteries shell it from Dogan Ridge. About two Keyes sends the 2nd Maine and 3rd Connecticut up the bare slope to the Robinson house. They reach the top, are driven off, and file away down Young's Branch out of the fight.", [-3000, 600], 3000, 120, None),
    ("14:00", "Ricketts and Griffin", "McDowell sends the two regular batteries onto Henry Hill south of the house, eleven guns 300 yards from Jackson's line, the Fire Zouaves and the Marines behind them. For a quarter of an hour the guns duel. Mrs. Judith Henry, bedridden, is mortally wounded in her house.", [-2700, -200], 1300, 20, "2:00 PM"),
    ("14:28", "Stuart's charge", "On the right of the guns the Fire Zouaves face the woods along the Sudley road. Stuart's 1st Virginia Cavalry rides out of them into the regiment's flank and scatters it.", [-2950, -450], 1200, 20, None),
    ("14:50", "The 33rd Virginia", "A regiment comes out of the brush toward Griffin's guns. Griffin takes it for the enemy; Major Barry, chief of artillery, tells him it is his support, and he holds his fire. At seventy yards the 33rd Virginia fires a volley that kills most of the gunners and horses. In 1861 both armies have men in blue and in grey.", [-2620, -330], 1000, 20, "about 3 PM"),
    ("15:05", "Up the hill one at a time", "The Union regiments go up from the Sudley road one at a time: the 14th Brooklyn, the 38th New York, the Massachusetts regiments, then Sherman's 2nd Wisconsin twice, the 79th and the 69th New York. The guns change hands three times and are never fired again. Bee and Bartow fall leading what is left of their brigades; Fisher of the 6th North Carolina is killed by the guns.", [-2800, -80], 1100, 20, None),
    ("15:30", "Kirby Smith", "Kirby Smith's brigade, off the cars near Manassas Junction, comes up from the south about half past three. Smith falls as it arrives and Elzey leads it on to the left. Sherman: 'Here, about 3.30 p.m., began the scene of confusion and disorder that characterized the remainder of the day.'", [-2900, -900], 2400, 30, "half past 3"),
    ("15:45", "The general advance", "Beauregard orders his whole line forward. Jackson's regiments, the 18th Virginia and the men on the left sweep the plateau to the Sudley road and take the guns for good.", [-2850, -150], 1900, 30, "about 3:45 PM"),
    ("16:00", "Blackburn's Ford", "On the Union left D. R. Jones's brigade comes down a ravine onto Davies's flank. Davies has his men lie down and six guns fire grape and canister into the column for half an hour; the 5th South Carolina holds the far slope three-quarters of an hour, alone, and goes back.", [4300, -150], 1700, 30, "about 4 PM"),
    ("16:12", "Chinn Ridge", "Howard's brigade, the last Union reserve, comes onto Chinn Ridge after the whole flank march. Elzey strikes it from the south-east, and Early, who has marched round the field, from the west; Kershaw's South Carolinians and Kemper's guns join in.", [-3600, -650], 1800, 20, None),
    ("16:30", "The retreat", "There is no order to retreat; the men go back of their own accord, most up the Sudley road and the woods road they came by, Sherman's and Keyes's over the Farm Ford. Sykes's regulars, Palmer's cavalry and Arnold's guns hold Buck Hill as the rear guard.", [-3200, 1500], 2800, 60, "4:30 PM"),
    ("18:12", "Cub Run", "Kemper's guns, pushed down the turnpike behind Kershaw, shell the Cub Run bridge; Edmund Ruffin is given the first shot. A wagon upsets on the bridge and the retreat becomes a panic. Guns, wagons and the carriages of the sightseers out from Washington are left behind, and Radford's troopers ride into the column.", [1500, 1800], 2400, 30, None),
    ("19:14", "Sunset", "McDowell reaches Centreville about sunset and tries to make a stand behind Miles's division. The Confederates are nearly as disordered by victory as the Union army by defeat, and there is no pursuit past Cub Run. Longstreet and Bonham, pushing up the roads from the fords, halt at dark and go back to Bull Run for water.", [3600, 1500], 4000, 120, "about sunset"),
    ("20:15", "Blenker's line", "Until about nine the stragglers stream through Blenker's regiments across the turnpike, the 8th New York a mile and a half out and the 29th half a mile behind. At midnight McDowell orders the army back to Washington. It rains on the 22nd.", [3300, 2250], 3200, 60, None),
]
events = [dict(t=t, title=a, text=b, at=at, view=v, speed=s, **({"when": w} if w else {})) for t, a, b, at, v, s, w in CHAPTERS]
